package com.lmspilot.notification.api;
import com.lmspilot.notification.domain.*;import com.lmspilot.notification.platform.NewsPolicy.*;import com.lmspilot.support.api.ApiException;import com.lmspilot.support.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
record NewsRequest(@NotBlank String title,@NotBlank String summary,@NotBlank String content,NewsStatus status,NewsAudienceType audienceType,UUID audienceId,Boolean pinned,Integer priority,Instant publishFrom,Instant publishUntil,List<UUID> attachmentFileIds){}record NewsResponse(UUID id,String title,String summary,String content,NewsStatus status,NewsAudienceType audienceType,UUID audienceId,boolean pinned,int priority,Instant publishFrom,Instant publishUntil,List<UUID> attachmentFileIds,boolean read,Instant createdAt,Instant updatedAt){}
@Service @Transactional class NewsService{private final NewsArticleRepository articles;private final NewsAttachmentRepository attachments;private final NewsReceiptRepository receipts;NewsService(NewsArticleRepository a,NewsAttachmentRepository f,NewsReceiptRepository r){articles=a;attachments=f;receipts=r;}List<NewsResponse> feed(){Instant now=Instant.now();return articles.findAllByStatusOrderByPinnedDescPriorityDescPublishFromDesc(NewsStatus.PUBLISHED).stream().filter(a->(a.publishFrom==null||!a.publishFrom.isAfter(now))&&(a.publishUntil==null||a.publishUntil.isAfter(now))).map(this::view).toList();}List<NewsResponse> manage(){return articles.findAll().stream().sorted(Comparator.comparing((NewsArticleEntity a)->a.updatedAt).reversed()).map(this::view).toList();}NewsResponse get(UUID id){return view(article(id));}NewsResponse create(NewsRequest i){NewsArticleEntity e=new NewsArticleEntity();apply(e,i);e.createdBy=user();return view(articles.save(e));}NewsResponse update(UUID id,NewsRequest i){NewsArticleEntity e=article(id);apply(e,i);e.updatedAt=Instant.now();return view(articles.save(e));}NewsResponse publish(UUID id){NewsArticleEntity e=article(id);e.status=NewsStatus.PUBLISHED;if(e.publishFrom==null)e.publishFrom=Instant.now();e.updatedAt=Instant.now();return view(articles.save(e));}NewsResponse archive(UUID id){NewsArticleEntity e=article(id);e.status=NewsStatus.ARCHIVED;e.updatedAt=Instant.now();return view(articles.save(e));}NewsResponse markRead(UUID id){article(id);NewsReceiptEntity r=receipts.findByNewsIdAndUserId(id,user()).orElseGet(NewsReceiptEntity::new);r.newsId=id;r.userId=user();receipts.save(r);return view(article(id));}private void apply(NewsArticleEntity e,NewsRequest i){new NewsAudience(i.audienceType()==null?NewsAudienceType.SYSTEM:i.audienceType(),i.audienceId());new NewsPublicationWindow(i.publishFrom(),i.publishUntil());e.title=i.title().trim();e.summary=i.summary().trim();e.content=i.content().trim();e.status=i.status()==null?NewsStatus.DRAFT:i.status();e.audienceType=i.audienceType()==null?NewsAudienceType.SYSTEM:i.audienceType();e.audienceId=i.audienceId();e.pinned=Boolean.TRUE.equals(i.pinned());e.priority=i.priority()==null?0:i.priority();e.publishFrom=i.publishFrom();e.publishUntil=i.publishUntil();articles.save(e);attachments.deleteAllByNewsId(e.id);if(i.attachmentFileIds()!=null)for(UUID f:i.attachmentFileIds()){NewsAttachmentEntity a=new NewsAttachmentEntity();a.newsId=e.id;a.fileId=f;attachments.save(a);}}private NewsArticleEntity article(UUID id){return articles.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NEWS_NOT_FOUND","Không tìm thấy tin tức"));}private NewsResponse view(NewsArticleEntity e){List<UUID> files=attachments.findAllByNewsId(e.id).stream().map(a->a.fileId).toList();boolean read=receipts.findByNewsIdAndUserId(e.id,user()).isPresent();return new NewsResponse(e.id,e.title,e.summary,e.content,e.status,e.audienceType,e.audienceId,e.pinned,e.priority,e.publishFrom,e.publishUntil,files,read,e.createdAt,e.updatedAt);}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}}}
@RestController @RequestMapping("/api/v1/news") public class NewsApi{private final NewsService service;public NewsApi(NewsService s){service=s;}@GetMapping public List<NewsResponse> feed(){return service.feed();}@GetMapping("/manage") public List<NewsResponse> manage(){return service.manage();}@GetMapping("/{id}") public NewsResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public NewsResponse create(@Valid @RequestBody NewsRequest i){return service.create(i);}@PutMapping("/{id}") public NewsResponse update(@PathVariable UUID id,@Valid @RequestBody NewsRequest i){return service.update(id,i);}@PostMapping("/{id}/publish") public NewsResponse publish(@PathVariable UUID id){return service.publish(id);}@PostMapping("/{id}/archive") public NewsResponse archive(@PathVariable UUID id){return service.archive(id);}@PostMapping("/{id}/read") public NewsResponse read(@PathVariable UUID id){return service.markRead(id);}}
